<?php
require_once dirname(__DIR__,2).'/app/helpers.php';require_role('admin');require_once dirname(__DIR__,2).'/app/Services/ReconciliationService.php';require_once dirname(__DIR__,2).'/app/Services/AdminOperationsService.php';$db=Database::connection();$svc=new ReconciliationService($db);$admin=new AdminOperationsService($db);$result=null;$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$result=$svc->run();}catch(Throwable $e){$error=$e->getMessage();}}$latest=$admin->latestReconciliation();
?><!doctype html><html lang="<?=e(current_locale())?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e(t('Reconciliation'))?> - <?=e(t('Admin'))?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><div class="container py-5"><div class="d-flex justify-content-between mb-4"><h2><?=e(t('Ledger Reconciliation'))?></h2><a href="<?=url('admin/')?>"><?=e(t('Admin dashboard'))?></a></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($result):?><div class="alert alert-<?=$result['status']==='passed'?'success':'danger'?>">Run #<?=e((string)$result['run_id'])?>: <?=e($result['status'])?> — <?=e((string)$result['accounts_checked'])?> <?=e(t('accounts checked'))?>, <?=e((string)count($result['mismatches']))?> <?=e(t('mismatches'))?>.</div><?php endif;?><div class="card border-0 shadow-sm"><div class="card-body"><h5><?=e(t('Latest run'))?></h5><?php if($latest):?><p><?=e(t('Status'))?>: <b><?=e(tx_label($latest['status']))?></b></p><p><?=e(t('Accounts checked'))?>: <?=e((string)$latest['accounts_checked'])?></p><p><?=e(t('Mismatches'))?>: <?=e((string)$latest['mismatches_found'])?></p><p><?=e(t('Completed'))?>: <?=e((string)$latest['completed_at'])?></p><?php else:?><p class="text-muted"><?=e(t('No reconciliation runs yet.'))?></p><?php endif;?><form method="post"><?=csrf_field()?><button class="btn btn-primary"><?=e(t('Run reconciliation'))?></button></form></div></div></div></body></html>
